// src/calculators/KTBundlingResult.jsx
import React from 'react';

export default function KTBundlingResult({ result }) {
  const { mobilePrice, internetPrice, tvPrice, total, discountRate, discountedTotal } = result;

  return (
    <div className="bg-white rounded-lg shadow p-4">
      <h2 className="text-xl font-semibold mb-3">계산 결과</h2>
      <ul className="space-y-1">
        <li>모바일 월 요금: {mobilePrice.toLocaleString()}원</li>
        <li>인터넷 월 요금: {internetPrice.toLocaleString()}원</li>
        <li>TV 월 요금: {tvPrice.toLocaleString()}원</li>
        <li>총 합계: {total.toLocaleString()}원</li>
        <li>결합 할인율: {(discountRate * 100).toFixed(0)}%</li>
        <li className="font-bold">할인 적용 총 금액: {discountedTotal.toLocaleString()}원</li>
      </ul>
    </div>
  );
}